function palindrome(s) {
  const n = String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
  return n === n.split('').reverse().join('');
}

function fizzbuzz(n) {
  const o = [];
  for (let i = 1; i <= n; i++) {
    let s = '';
    if (i % 3 === 0) s += 'fizz';
    if (i % 5 === 0) s += 'buzz';
    o.push(s || String(i));
  }
  return o;
}

function jumlah(a, b) {
  return Number(a) + Number(b);
}
jumlah(2, 3);

